import{n as e,r as t,t as n}from"./globals-Cg1fFObX.js";var r=t(),i=e(),a=n(),o=`https://openai.com/index/ten-advances-in-mathematics/`,s=`https://github.com/openai/ten-proofs`;function c(){return(0,a.jsxs)(`main`,{className:`essayPage`,children:[(0,a.jsxs)(`header`,{className:`topbar`,children:[(0,a.jsx)(`a`,{className:`brand`,href:`../../`,"aria-label":`Proof of Progress home`,children:`Proof of Progress`}),(0,a.jsxs)(`nav`,{"aria-label":`Essay navigation`,children:[(0,a.jsx)(`a`,{href:`../../`,children:`Data`}),(0,a.jsx)(`a`,{href:`../../report/ai-mathematical-proof-analysis.pdf`,children:`Report`})]})]}),(0,a.jsxs)(`article`,{className:`essayArticle`,children:[(0,a.jsxs)(`header`,{className:`essayHeader`,children:[(0,a.jsx)(`p`,{className:`eyebrow`,children:`Essay · 2 August 2026`}),(0,a.jsx)(`h1`,{children:`After the open problem`}),(0,a.jsx)(`p`,{className:`essayStandfirst`,children:`AI is not exhausting mathematics. It is changing the economics of producing proofs faster than mathematical institutions are changing the economics of producing mathematicians.`}),(0,a.jsx)(`div`,{className:`essayByline`,children:`Alastair Moore · Proof of Progress`})]}),(0,a.jsx)(`p`,{className:`essayDropcap`,children:`When OpenAI announced ten advances across geometry, coding theory, complexity, group theory, operator algebras, cryptography and combinatorics, the striking fact was not only that an internal model had found the arguments. The company reported that the search tokens would cost roughly $2,000 at its Sol API rates, that humans then prepared manuscripts with the model, and that the model produced Lean certificates for the results. A collection of research questions that had resisted progress for at least a decade had been turned into a compact production run.`}),(0,a.jsx)(`p`,{children:`The announcement immediately produced two incompatible pictures of what had happened. In one, AI was “sterilizing” branches of mathematics: removing the unsolved questions through which people win recognition, build careers and experience discovery. In the other, open problems were renewable. Every solution creates concepts, techniques and sharper questions; mathematics is mostly what we do not know, and the unknown is larger than any plausible solving machine can clear.`}),(0,a.jsx)(`p`,{children:`Both pictures see something real, but neither quite names the central problem. The supply of unknown propositions is not the same thing as the supply of good human research roles. Mathematics may remain inexhaustible while the institutions that train and employ mathematicians become brittle. The danger is not that there will be nothing left to prove. It is that the route by which a person learns to notice what is worth proving, acquires technique, earns trust and joins a community may no longer be financed by the production of proofs.`}),(0,a.jsx)(`h2`,{children:`The wrong unit of account`}),(0,a.jsx)(`p`,{children:`“Ten solved problems” is irresistible language, but it is a poor analytical unit. A complete proof, a counterexample, a sharper bound and a portfolio of related constructions do not close mathematical territory in the same way. Nor is one published package necessarily one unique problem. Proof Progress was built around this accounting difficulty. Its curve counts source-included public result packages, while its ledger separately records the advance, the prior target, the scope, resistance, verification and provisional status.`}),(0,a.jsx)(`p`,{children:`That separation matters. A kernel-checked proof establishes deduction relative to a formal statement and environment. It does not on its own establish that the statement faithfully captures the informal claim, that the claim is new, that it matters, or that the account of who contributed what is adequate. Conversely, a result can be mathematically illuminating before it is fully formalized. Verification is a stack: formal correctness, semantic fidelity, novelty, significance and reproducibility. Treating the first layer as the whole stack mistakes an extraordinary instrument for a complete institution.`}),(0,a.jsxs)(`aside`,{className:`essayCallout`,children:[(0,a.jsx)(`strong`,{children:`Proof of Progress keeps four questions apart.`}),(0,a.jsx)(`span`,{children:`What was produced? How difficult was the target? How was it checked? What role did AI play?`})]}),(0,a.jsx)(`p`,{children:`Cost needs the same discipline. The reported API-equivalent figure is evidence that inference can be cheap once the system exists. It is not the total cost of the research: training the model, building the surrounding system, choosing and preparing targets, absorbing unsuccessful searches, writing the manuscripts, maintaining Lean libraries and obtaining expert scrutiny all sit outside that number. Cheap proof search can still be transformative. But institutional decisions should be made from the full production function, not the marginal price printed on its final stage.`}),(0,a.jsx)(`h2`,{children:`Problems renew; apprenticeships do not`}),(0,a.jsx)(`p`,{children:`The strongest answer to the sterilization metaphor is that solutions are generative. A proof can expose an unexpected bridge between fields, create a reusable lemma, reveal that a conjecture was posed at the wrong level of generality, or turn one question into a programme. OpenAI itself asks the community to place the new arguments in context and bring their ideas to life. There is no fixed barrel of theorems from which each solution removes one scarce object.`}),(0,a.jsx)(`p`,{children:`Yet renewal is not automatic. New questions vary in prestige, accessibility and pedagogical value. Some arrive only after a specialist has spent months understanding why a machine-generated argument works. Others may be visible mainly to the same systems that produced the preceding result. The relevant quantity is therefore not the gross number of unanswered questions. It is the rate at which solved work generates research roles in which people can develop judgment and make recognized contributions.`}),(0,a.jsx)(`p`,{children:`This is especially important for junior researchers. Mathematical taste is not learned from a list of open problems. It develops through failed approaches, partial lemmas, seminars, referee reports, computation, exposition and the slow acquisition of a sense for which definitions will bear weight. Those tasks have doubled as apprenticeship and as publishable output. If automated systems absorb the tractable middle of projects, senior mathematicians may become more productive while the path to becoming a senior mathematician erodes beneath them.`}),(0,a.jsx)(`p`,{children:`The response cannot be to preserve inefficient work for its own sake. It should be to stop using theorem ownership as the sole proxy for mathematical development. Training and evaluation can explicitly reward problem formulation, conceptual synthesis, adversarial checking, formal specification, explanatory reconstruction and the creation of datasets and libraries that make later discovery possible. These are not consolation prizes. In an automated research system they are part of the epistemic machinery.`}),(0,a.jsx)(`h2`,{children:`From industrial support to public capacity`}),(0,a.jsx)(`p`,{children:`Industrial support will be useful because frontier proof systems require compute, engineering and operational knowledge that universities cannot instantly reproduce. But “industrial support” can mean two very different arrangements. It can expand the community’s capabilities, or it can concentrate access, target selection and disclosure inside a few laboratories. A healthy settlement requires more than occasional model grants. It requires durable access for researchers, shared formalization infrastructure, independent replication funds, disclosure standards and institutions able to challenge a laboratory’s account of its own results.`}),(0,a.jsx)(`p`,{children:`Attribution is one early test. Saying that a model generated an argument is more honest than laundering it into conventional human authorship. But honest attribution also needs a record of target selection, prompting and orchestration, manuscript intervention, formal translation, verification and failed runs. Without workflow provenance, readers cannot distinguish autonomy from a tightly scaffolded collaboration or reproduce the conditions under which success occurred.`}),(0,a.jsx)(`p`,{children:`The same is true of headline capability. Ten selected successes are strong evidence of a new capacity; they are not a denominator. We also need to know the candidate pool, success rate, selection procedure, compute distribution and the fate of outputs that were wrong, trivial or already known. Proof of Progress is deliberately modest on this point: a chronology of source-included public outputs can show a take-off in production, but it cannot by itself measure a model’s general probability of solving an unseen research problem.`}),(0,a.jsx)(`h2`,{children:`A compact for proof after automation`}),(0,a.jsx)(`p`,{children:`The useful question is not whether humans or machines should do mathematics. Both already do, inside systems assembled by people and judged by communities. The question is what arrangement produces reliable knowledge while renewing the human capacity to understand, criticize and choose.`}),(0,a.jsx)(`p`,{children:`Universities should redesign doctoral training around model-aware research without outsourcing judgment to models. Journals and prizes should require contribution statements that make problem choice, argument generation, formalization and verification visible. Funders should pay for independent checking and explanatory work, not only first solutions. Laboratories should publish enough negative evidence to make capability claims interpretable. And access programmes should be treated as shared scientific infrastructure rather than discretionary patronage.`}),(0,a.jsx)(`p`,{children:`The social-media debate was therefore right to sound both excited and alarmed. The Astra results, as presented, are not the end of mathematical research. Nor are they merely another tool arriving into an otherwise stable profession. They are a stress test for a reward system built when producing a proof was expensive and tightly coupled to producing a mathematician.`}),(0,a.jsx)(`p`,{children:`Open problems are renewable. The harder task is to make mathematical culture renewable too. That means preserving not a protected stock of unsolved questions, but a plural ecology in which solutions lead to understanding, understanding leads to new questions, and new researchers still have a credible way to become the people capable of asking them.`}),(0,a.jsxs)(`section`,{className:`essaySources`,"aria-labelledby":`essay-sources`,children:[(0,a.jsx)(`h2`,{id:`essay-sources`,children:`Sources and project links`}),(0,a.jsxs)(`ul`,{children:[(0,a.jsx)(`li`,{children:(0,a.jsx)(`a`,{href:o,children:`OpenAI: Ten advances in mathematics and theoretical computer science ↗`})}),(0,a.jsx)(`li`,{children:(0,a.jsx)(`a`,{href:s,children:`Lean certificates for the ten results ↗`})}),(0,a.jsx)(`li`,{children:(0,a.jsx)(`a`,{href:`../../`,children:`Explore the Proof of Progress evidence dashboard`})}),(0,a.jsx)(`li`,{children:(0,a.jsx)(`a`,{href:`../../report/ai-mathematical-proof-analysis.pdf`,children:`Read the full Proof of Progress report`})})]}),(0,a.jsx)(`p`,{children:`This essay responds to the public discussion summarized on 2 August 2026. Claims about the ten results and their production follow OpenAI’s announcement; the broader institutional analysis is the author’s interpretation. Formal certificates support deductive checking but do not by themselves settle novelty, significance, semantic fidelity or attribution.`})]})]}),(0,a.jsxs)(`footer`,{className:`essayFooter`,children:[(0,a.jsxs)(`div`,{children:[(0,a.jsx)(`strong`,{children:`Proof of Progress`}),(0,a.jsx)(`p`,{children:`A source-included, AI-coded, unreviewed record of contributions to mathematical research.`})]}),(0,a.jsx)(`a`,{href:`../../`,children:`Return to the project →`})]})]})}var l=document.getElementById(`root`);if(!l)throw Error(`Static essay root is missing`);(0,i.createRoot)(l).render((0,a.jsx)(r.StrictMode,{children:(0,a.jsx)(c,{})}));